Here's a C# equivalent of your Python script using AWS SDK for .NET (AWSSDK.Lambda). This script will delete inactive Lambda function versions that haven't been modified in more than 7 days, excluding the `$LATEST` version.

### ✅ Prerequisites:
- Install the AWS SDK for .NET via NuGet:
  ```
  Install-Package AWSSDK.Lambda
  ```
- Ensure you have AWS credentials configured (via `~/.aws/credentials` or environment variables).

---

### ✅ C# Equivalent Code

```csharp
using System;
using System.Collections.Generic;
using System.Linq;
using Amazon.Lambda;
using Amazon.Lambda.Model;
using Amazon;
using System.Threading.Tasks;

class Program
{
    static async Task Main(string[] args)
    {
        string regionName = "us-east-1";
        await DeleteInactiveLambdaFunctions(regionName);
    }

    public static async Task DeleteInactiveLambdaFunctions(string regionName)
    {
        // Initialize the AWS Lambda client
        var lambdaClient = new AmazonLambdaClient(RegionEndpoint.GetBySystemName(regionName));

        // List all Lambda functions in the specified region
        var listFunctionsRequest = new ListFunctionsRequest();
        var listFunctionsResponse = await lambdaClient.ListFunctionsAsync(listFunctionsRequest);
        var functions = listFunctionsResponse.Functions;

        foreach (var function in functions)
        {
            string functionName = function.FunctionName;

            // List all versions of the function (excluding $LATEST)
            var listVersionsRequest = new ListVersionsByFunctionRequest
            {
                FunctionName = functionName
            };
            var listVersionsResponse = await lambdaClient.ListVersionsByFunctionAsync(listVersionsRequest);
            var versions = listVersionsResponse.Versions;

            // Filter out $LATEST version
            var nonLatestVersions = versions.Where(v => v.Version != "$LATEST").ToList();

            foreach (var version in nonLatestVersions)
            {
                // Skip versions that are referenced by an alias
                if (version.Aliases.Contains(version.Version))
                {
                    continue;
                }

                // Check if the version is inactive (last modified more than 7 days ago)
                var lastModified = version.LastModified;
                var now = DateTime.UtcNow;

                if ((now - lastModified).Days > 7)
                {
                    try
                    {
                        // Delete the inactive version
                        var deleteFunctionRequest = new DeleteFunctionRequest
                        {
                            FunctionName = functionName,
                            Qualifier = version.Version
                        };
                        await lambdaClient.DeleteFunctionAsync(deleteFunctionRequest);
                        Console.WriteLine($"Deleted inactive version {version.Version} of function {functionName}");
                    }
                    catch (Exception ex)
                    {
                        Console.WriteLine($"Error deleting version {version.Version} of function {functionName}: {ex.Message}");
                    }
                }
            }
        }
    }
}
```

---

### 🔍 Notes:
- **`ListFunctionsAsync`** retrieves all Lambda functions in the region.
- **`ListVersionsByFunctionAsync`** gets all versions of a function.
- **`DeleteFunctionAsync`** deletes a specific version.
- The script skips versions that are referenced by an alias.
- It uses `DateTime.UtcNow` for time comparison in UTC, matching the Python version.

